import Foundation

struct InsightsBadge: Identifiable {
    let id: String
    let title: String
    let requirement: String
    let icon: String
    let unlocked: Bool
    let progress: String
}

extension InsightsSnapshot {
    var badges: [InsightsBadge] {
        let total = totalDuration / 3600
        return [
            .init(id: "first", title: String(localized: "First session", bundle: .app), requirement: String(localized: "Complete your first session", bundle: .app), icon: "flag.fill", unlocked: total > 0, progress: String(localized: "\(sessionCount) sessions", bundle: .app)),
            .init(id: "ten", title: String(localized: "10-hour club", bundle: .app), requirement: String(localized: "Work 10 total hours", bundle: .app), icon: "clock.fill", unlocked: total >= 10, progress: progressText(DurationText.compact(total * 3600), String(localized: "10h", bundle: .app))),
            .init(id: "fifty", title: String(localized: "Half-century", bundle: .app), requirement: String(localized: "Work 50 total hours", bundle: .app), icon: "flame.fill", unlocked: total >= 50, progress: progressText(DurationText.compact(total * 3600), String(localized: "50h", bundle: .app))),
            .init(id: "hundred", title: String(localized: "Century", bundle: .app), requirement: String(localized: "Work 100 total hours", bundle: .app), icon: "bolt.fill", unlocked: total >= 100, progress: progressText(DurationText.compact(total * 3600), String(localized: "100h", bundle: .app))),
            .init(id: "quarter", title: String(localized: "Quarter kilo", bundle: .app), requirement: String(localized: "Work 250 total hours", bundle: .app), icon: "crown.fill", unlocked: total >= 250, progress: progressText(DurationText.compact(total * 3600), String(localized: "250h", bundle: .app))),
            .init(id: "fivehundred", title: String(localized: "Half-thousand", bundle: .app), requirement: String(localized: "Work 500 total hours", bundle: .app), icon: "crown.fill", unlocked: total >= 500, progress: progressText(DurationText.compact(total * 3600), String(localized: "500h", bundle: .app))),
            .init(id: "sevenfifty", title: String(localized: "Three-quarter legend", bundle: .app), requirement: String(localized: "Work 750 total hours", bundle: .app), icon: "medal.fill", unlocked: total >= 750, progress: progressText(DurationText.compact(total * 3600), String(localized: "750h", bundle: .app))),
            .init(id: "thousand", title: String(localized: "Thousand-hour", bundle: .app), requirement: String(localized: "Work 1,000 total hours", bundle: .app), icon: "trophy.fill", unlocked: total >= 1_000, progress: progressText(DurationText.compact(total * 3600), String(localized: "1,000h", bundle: .app))),
            .init(id: "titan", title: String(localized: "Time titan", bundle: .app), requirement: String(localized: "Work 1,500 total hours", bundle: .app), icon: "diamond.fill", unlocked: total >= 1_500, progress: progressText(DurationText.compact(total * 3600), String(localized: "1,500h", bundle: .app))),
            .init(id: "streak", title: String(localized: "On a roll", bundle: .app), requirement: String(localized: "Keep a 3-day streak", bundle: .app), icon: "flame.circle.fill", unlocked: currentStreak >= 3, progress: progressText(String(currentStreak), String(localized: "3 days", bundle: .app))),
            .init(id: "weekstreak", title: String(localized: "Weekly fire", bundle: .app), requirement: String(localized: "Keep a 7-day streak", bundle: .app), icon: "calendar.badge.clock", unlocked: currentStreak >= 7, progress: progressText(String(currentStreak), String(localized: "7 days", bundle: .app))),
            .init(id: "monthstreak", title: String(localized: "Unstoppable", bundle: .app), requirement: String(localized: "Keep a 30-day streak", bundle: .app), icon: "infinity", unlocked: currentStreak >= 30, progress: progressText(String(currentStreak), String(localized: "30 days", bundle: .app))),
            .init(id: "streak14", title: String(localized: "Fortnight fire", bundle: .app), requirement: String(localized: "Reach a 14-day streak", bundle: .app), icon: "sparkles", unlocked: longestStreak >= 14, progress: progressText(String(longestStreak), String(localized: "14 days", bundle: .app))),
            .init(id: "streak60", title: String(localized: "Seasoned", bundle: .app), requirement: String(localized: "Reach a 60-day streak", bundle: .app), icon: "mountain.2.fill", unlocked: longestStreak >= 60, progress: progressText(String(longestStreak), String(localized: "60 days", bundle: .app))),
            .init(id: "week", title: String(localized: "Weekly finisher", bundle: .app), requirement: String(localized: "Log 7 sessions", bundle: .app), icon: "calendar.badge.plus", unlocked: sessionCount >= 7, progress: progressText(String(sessionCount), String(localized: "7 sessions", bundle: .app))),
            .init(id: "sessions25", title: String(localized: "Session collector", bundle: .app), requirement: String(localized: "Log 25 sessions", bundle: .app), icon: "square.stack.3d.up.fill", unlocked: sessionCount >= 25, progress: progressText(String(sessionCount), String(localized: "25 sessions", bundle: .app))),
            .init(id: "marathon", title: String(localized: "Marathon", bundle: .app), requirement: String(localized: "Complete a 4-hour session", bundle: .app), icon: "figure.run", unlocked: longestSession >= 4 * 3600, progress: progressText(DurationText.compact(longestSession), String(localized: "4h", bundle: .app))),
