            .init(id: "xp", title: String(localized: "XP engine", bundle: .app), requirement: String(localized: "Earn 10,000 XP", bundle: .app), icon: "star.fill", unlocked: xp >= 10_000, progress: progressText(String(xp), String(localized: "10,000 XP", bundle: .app))),
            // Mac'teki hedef rozetlerinin yerine sabit esikler: hedef
            // kullanicinin sectigi bir sayi oldugu icin istenildigi kadar
            // kucultulup rozet acilabiliyordu.
            .init(id: "fullday", title: String(localized: "Full day", bundle: .app), requirement: String(localized: "Work 8 hours in one day", bundle: .app), icon: "target", unlocked: fullDays >= 1, progress: String(localized: "\(fullDays) 8-hour days", bundle: .app)),
            .init(id: "longday", title: String(localized: "Long day", bundle: .app), requirement: String(localized: "Work 10 hours in one day", bundle: .app), icon: "arrow.up.right.circle.fill", unlocked: longDays >= 1, progress: String(localized: "\(longDays) 10-hour days", bundle: .app)),
            .init(id: "bigmonth", title: String(localized: "Hundred-hour month", bundle: .app), requirement: String(localized: "Work 100 hours in a calendar month", bundle: .app), icon: "calendar.circle.fill", unlocked: bigMonths >= 1, progress: String(localized: "\(bigMonths) 100-hour months", bundle: .app)),
            .init(id: "xp25", title: String(localized: "Quarter XP", bundle: .app), requirement: String(localized: "Earn 25,000 XP", bundle: .app), icon: "rosette", unlocked: xp >= 25_000, progress: progressText(String(xp), String(localized: "25,000 XP", bundle: .app))),
            .init(id: "active5", title: String(localized: "Getting steady", bundle: .app), requirement: String(localized: "Work on 5 different days", bundle: .app), icon: "calendar", unlocked: daily.count >= 5, progress: progressText(String(daily.count), String(localized: "5 active days", bundle: .app))),
            .init(id: "active25", title: String(localized: "Calendar regular", bundle: .app), requirement: String(localized: "Work on 25 different days", bundle: .app), icon: "calendar.badge.checkmark", unlocked: daily.count >= 25, progress: progressText(String(daily.count), String(localized: "25 active days", bundle: .app))),
            .init(id: "active100", title: String(localized: "Daily craft", bundle: .app), requirement: String(localized: "Work on 100 different days", bundle: .app), icon: "calendar.circle", unlocked: daily.count >= 100, progress: progressText(String(daily.count), String(localized: "100 active days", bundle: .app))),
            .init(id: "earlybird", title: String(localized: "Early bird", bundle: .app), requirement: String(localized: "Start 5 sessions before 08:00", bundle: .app), icon: "sunrise.fill", unlocked: earlyBirdSessions >= 5, progress: progressText(String(earlyBirdSessions), String(localized: "5 early starts", bundle: .app))),
            .init(id: "nightowl", title: String(localized: "Night owl", bundle: .app), requirement: String(localized: "Start 5 sessions after 22:00", bundle: .app), icon: "moon.stars.fill", unlocked: nightOwlSessions >= 5, progress: progressText(String(nightOwlSessions), String(localized: "5 late starts", bundle: .app))),
            .init(id: "weekend", title: String(localized: "Weekend warrior", bundle: .app), requirement: String(localized: "Work on 4 weekend days", bundle: .app), icon: "sun.max.fill", unlocked: weekendDays >= 4, progress: progressText(String(weekendDays), String(localized: "4 weekend days", bundle: .app))),
            .init(id: "sessions50", title: String(localized: "Deep archive", bundle: .app), requirement: String(localized: "Log 50 sessions", bundle: .app), icon: "books.vertical.fill", unlocked: sessionCount >= 50, progress: progressText(String(sessionCount), String(localized: "50 sessions", bundle: .app))),
            .init(id: "sessions100", title: String(localized: "Century sessions", bundle: .app), requirement: String(localized: "Log 100 sessions", bundle: .app), icon: "building.columns.fill", unlocked: sessionCount >= 100, progress: progressText(String(sessionCount), String(localized: "100 sessions", bundle: .app))),
            .init(id: "sessions200", title: String(localized: "Archive master", bundle: .app), requirement: String(localized: "Log 200 sessions", bundle: .app), icon: "square.stack.3d.up.fill", unlocked: sessionCount >= 200, progress: progressText(String(sessionCount), String(localized: "200 sessions", bundle: .app))),
            .init(id: "sessions500", title: String(localized: "Session institution", bundle: .app), requirement: String(localized: "Log 500 sessions", bundle: .app), icon: "building.2.crop.circle.fill", unlocked: sessionCount >= 500, progress: progressText(String(sessionCount), String(localized: "500 sessions", bundle: .app))),
            .init(id: "ultra12", title: String(localized: "Iron focus", bundle: .app), requirement: String(localized: "Complete a 12-hour session", bundle: .app), icon: "hourglass.bottomhalf.filled", unlocked: longestSession >= 12 * 3600, progress: progressText(DurationText.compact(longestSession), String(localized: "12h", bundle: .app))),
            .init(id: "ultra15", title: String(localized: "Deep dive", bundle: .app), requirement: String(localized: "Complete a 15-hour session", bundle: .app), icon: "water.waves", unlocked: longestSession >= 15 * 3600, progress: progressText(DurationText.compact(longestSession), String(localized: "15h", bundle: .app))),
            .init(id: "fullday7", title: String(localized: "Full week", bundle: .app), requirement: String(localized: "Work 8 hours on 7 days", bundle: .app), icon: "checkmark.seal.fill", unlocked: fullDays >= 7, progress: progressText(String(fullDays), String(localized: "7 8-hour days", bundle: .app))),
            .init(id: "fullday30", title: String(localized: "Full month", bundle: .app), requirement: String(localized: "Work 8 hours on 30 days", bundle: .app), icon: "target", unlocked: fullDays >= 30, progress: progressText(String(fullDays), String(localized: "30 8-hour days", bundle: .app))),
            .init(id: "bigmonth3", title: String(localized: "Quarter of hundreds", bundle: .app), requirement: String(localized: "Work 100 hours in 3 calendar months", bundle: .app), icon: "calendar.badge.checkmark", unlocked: bigMonths >= 3, progress: progressText(String(bigMonths), String(localized: "3 100-hour months", bundle: .app))),
            .init(id: "bigmonth12", title: String(localized: "Year of hundreds", bundle: .app), requirement: String(localized: "Work 100 hours in 12 calendar months", bundle: .app), icon: "calendar.badge.clock", unlocked: bigMonths >= 12, progress: progressText(String(bigMonths), String(localized: "12 100-hour months", bundle: .app))),
            .init(id: "streak90", title: String(localized: "Season streak", bundle: .app), requirement: String(localized: "Reach a 90-day streak", bundle: .app), icon: "flame.circle.fill", unlocked: longestStreak >= 90, progress: progressText(String(longestStreak), String(localized: "90 days", bundle: .app))),
            .init(id: "streak180", title: String(localized: "Half-year fire", bundle: .app), requirement: String(localized: "Reach a 180-day streak", bundle: .app), icon: "sun.max.fill", unlocked: longestStreak >= 180, progress: progressText(String(longestStreak), String(localized: "180 days", bundle: .app))),
            .init(id: "streak365", title: String(localized: "Year-round", bundle: .app), requirement: String(localized: "Reach a 365-day streak", bundle: .app), icon: "globe.americas.fill", unlocked: longestStreak >= 365, progress: progressText(String(longestStreak), String(localized: "365 days", bundle: .app))),
            .init(id: "active250", title: String(localized: "Always on", bundle: .app), requirement: String(localized: "Work on 250 different days", bundle: .app), icon: "calendar.badge.clock", unlocked: daily.count >= 250, progress: progressText(String(daily.count), String(localized: "250 active days", bundle: .app))),
            .init(id: "active500", title: String(localized: "Permanent practice", bundle: .app), requirement: String(localized: "Work on 500 different days", bundle: .app), icon: "calendar.circle.fill", unlocked: daily.count >= 500, progress: progressText(String(daily.count), String(localized: "500 active days", bundle: .app))),
            .init(id: "xp50", title: String(localized: "XP architect", bundle: .app), requirement: String(localized: "Earn 50,000 XP", bundle: .app), icon: "star.circle.fill", unlocked: xp >= 50_000, progress: progressText(String(xp), String(localized: "50,000 XP", bundle: .app))),
            .init(id: "xp100", title: String(localized: "XP legend", bundle: .app), requirement: String(localized: "Earn 100,000 XP", bundle: .app), icon: "sparkles", unlocked: xp >= 100_000, progress: progressText(String(xp), String(localized: "100,000 XP", bundle: .app)))
        ] + collectionBadges
